62	fn parse_utility_name(p: &mut CssParser) -> ParsedSyntax {
63	    // Check if this is a functional utility (ends with -*)
64	    if is_at_functional_utility_name(p) {
65	        // Functional utility: tab-*
66	        let m = p.start();
67	
68	        parse_utility_identifier(p).ok();
69	        p.expect(T![-]);
70	        p.expect(T![*]);
71	
72	        Present(m.complete(p, TW_FUNCTIONAL_UTILITY_NAME))
73	    } else {
74	        // Simple utility: center-flex
75	        parse_utility_identifier(p)
76	    }
77	}
