19	pub enum CssLexContext {
20	    /// Default context: no particular rules are applied to the lexer logic.
21	    #[default]
22	    Regular,
23	    /// Applied when lexing CSS selectors.
24	    /// Doesn't skip whitespace trivia for a combinator.
25	    Selector,
26	
27	    /// Applied when lexing CSS pseudo nth selectors.
28	    /// Distinct '-' from identifiers and '+' from numbers.
29	    PseudoNthSelector,
30	
31	    /// Applied when lexing CSS url function.
32	    /// Greedily consume tokens in the URL function until encountering ")"
33	    UrlRawValue,
34	
35	    /// Applied when lexing CSS color literals.
36	    /// Starting from #
37	    /// support #000 #000f #ffffff #ffffffff
38	    /// https://drafts.csswg.org/css-color/#typedef-hex-color
39	    Color,
40	
41	    /// Applied when lexing CSS unicode range.
42	    /// Starting from U+ or u+
